steps.command:
Get-ChildItem .\eshopp.Report\definition\pages -Directory |
Where-Object {
  (Get-Content -Encoding UTF8 -Raw -Path (Join-Path $_.FullName "page.json") | ConvertFrom-Json).displayName -eq "CEO Dashboard"
} |
Get-ChildItem -Recurse -Filter visual.json |
ForEach-Object {
  Get-Content -Encoding UTF8 -Raw -LiteralPath $_.FullName | ConvertFrom-Json | ConvertTo-Json -Compress -Depth 100
}

