steps.command:
$ErrorActionPreference = 'Stop'
$report = Get-Content -Encoding UTF8 -Raw .\eshopp.Report\definition\report.json | ConvertFrom-Json
$themes = @(
  foreach ($theme in @($report.themeCollection.baseTheme, $report.themeCollection.customTheme)) {
    if ($null -eq $theme) { continue }
    $package = $report.resourcePackages | Where-Object { $_.type -eq $theme.type }
    $resource = $package.items | Where-Object { $_.name -eq $theme.name }
    $path = Join-Path (Join-Path .\eshopp.Report\StaticResources $package.name) $resource.path
    Get-Content -Encoding UTF8 -Raw -LiteralPath $path | ConvertFrom-Json
  }
)
$visuals = @(
  Get-ChildItem .\eshopp.Report\definition\pages -Directory |
  Where-Object {
    (Get-Content -Encoding UTF8 -Raw -LiteralPath (Join-Path $_.FullName 'page.json') | ConvertFrom-Json).displayName -eq 'CEO Dashboard'
  } |
  Get-ChildItem -Recurse -Filter visual.json |
  ForEach-Object { Get-Content -Encoding UTF8 -Raw -LiteralPath $_.FullName | ConvertFrom-Json }
)
@{ themes = $themes; visuals = $visuals } | ConvertTo-Json -Compress -Depth 100

expects:
jq check: {"inputMode": "json", "query": "def border_shown($themes):
  .visual as $visual |
  [
    false,
    ($themes[] | .visualStyles | (.["*"], .[$visual.visualType]) | .["*"].border[]?.show),
    ($visual.visualContainerObjects.border[]?.properties.show.expr.Literal.Value | select(. != null) | . == "true")
  ] | map(select(. != null)) | last;
.themes as $themes |
any(.visuals[]; .visual.visualType == "donutChart" and border_shown($themes))
", "expectedResults": [{"type": "bool", "operator": "==", "value": true}]}

